// ************
// Types
// ************

import '@dev.hiconic/gm_resource-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import BlobSource = T.com.braintribe.model.resource.source.BlobSource;
export import ConversionServiceSource = T.com.braintribe.model.resource.source.ConversionServiceSource;
export import FileSystemSource = T.com.braintribe.model.resource.source.FileSystemSource;
export import FileUploadSource = T.com.braintribe.model.resource.source.FileUploadSource;
export import ImageSpecification = T.com.braintribe.model.resource.specification.ImageSpecification;
export import OcrSpecification = T.com.braintribe.model.resource.specification.OcrSpecification;
export import PageCountSpecification = T.com.braintribe.model.resource.specification.PageCountSpecification;
export import PdfSpecification = T.com.braintribe.model.resource.specification.PdfSpecification;
export import PhysicalDimensionSpecification = T.com.braintribe.model.resource.specification.PhysicalDimensionSpecification;
export import PixelDimensionSpecification = T.com.braintribe.model.resource.specification.PixelDimensionSpecification;
export import RasterImageSpecification = T.com.braintribe.model.resource.specification.RasterImageSpecification;
export import SqlSource = T.com.braintribe.model.resource.source.SqlSource;
export import StaticSource = T.com.braintribe.model.resource.source.StaticSource;
export import StringSource = T.com.braintribe.model.resource.source.StringSource;
export import TemplateSource = T.com.braintribe.model.resource.source.TemplateSource;
export import UploadSource = T.com.braintribe.model.resource.source.UploadSource;
export import UrlUploadSource = T.com.braintribe.model.resource.source.UrlUploadSource;
export import VectorImageSpecification = T.com.braintribe.model.resource.specification.VectorImageSpecification;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.resource.source {

		const BlobSource: hc.reflection.EntityType<BlobSource>;
		type BlobSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.BlobSource">;

		const ConversionServiceSource: hc.reflection.EntityType<ConversionServiceSource>;
		type ConversionServiceSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.ConversionServiceSource">;

		const FileSystemSource: hc.reflection.EntityType<FileSystemSource>;
		type FileSystemSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.FileSystemSource", {
			path: string;
		}>;

		const FileUploadSource: hc.reflection.EntityType<FileUploadSource>;
		type FileUploadSource = UploadSource &
		  Entity<"com.braintribe.model.resource.source.FileUploadSource", {
			localFilePath: string;
		}>;

		const SqlSource: hc.reflection.EntityType<SqlSource>;
		type SqlSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.SqlSource", {
			blobId: string;
		}>;

		const StaticSource: hc.reflection.EntityType<StaticSource>;
		type StaticSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.StaticSource", {
			resolverURI: string;
		}>;

		const StringSource: hc.reflection.EntityType<StringSource>;
		type StringSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.StringSource", {
			content: string;
			encoding: string;
		}>;

		const TemplateSource: hc.reflection.EntityType<TemplateSource>;
		type TemplateSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.TemplateSource", {
			template: T.com.braintribe.model.resource.Resource;
		}>;

		const UploadSource: hc.reflection.EntityType<UploadSource>;
		type UploadSource = ResourceSource &
		  Entity<"com.braintribe.model.resource.source.UploadSource">;

		const UrlUploadSource: hc.reflection.EntityType<UrlUploadSource>;
		type UrlUploadSource = UploadSource &
		  Entity<"com.braintribe.model.resource.source.UrlUploadSource", {
			url: string;
		}>;

	}

	namespace T.com.braintribe.model.resource.specification {

		const ImageSpecification: hc.reflection.EntityType<ImageSpecification>;
		type ImageSpecification = PhysicalDimensionSpecification & PageCountSpecification &
		  Entity<"com.braintribe.model.resource.specification.ImageSpecification", {
			format: string;
		}>;

		const OcrSpecification: hc.reflection.EntityType<OcrSpecification>;
		type OcrSpecification = PixelDimensionSpecification & PhysicalDimensionSpecification &
		  Entity<"com.braintribe.model.resource.specification.OcrSpecification">;

		const PageCountSpecification: hc.reflection.EntityType<PageCountSpecification>;
		type PageCountSpecification = ResourceSpecification &
		  Entity<"com.braintribe.model.resource.specification.PageCountSpecification", {
			pageCount: P<integer, { nullable: false }>;
		}>;

		const PdfSpecification: hc.reflection.EntityType<PdfSpecification>;
		type PdfSpecification = PhysicalDimensionSpecification & PageCountSpecification &
		  Entity<"com.braintribe.model.resource.specification.PdfSpecification", {
			detectPageRotation: P<boolean, { nullable: false }>;
			ignoreInvalidImages: P<boolean, { nullable: false }>;
			imageAlignment: P<integer, { nullable: false }>;
			scaleTiffByDpi: P<boolean, { nullable: false }>;
		}>;

		const PhysicalDimensionSpecification: hc.reflection.EntityType<PhysicalDimensionSpecification>;
		type PhysicalDimensionSpecification = ResourceSpecification &
		  Entity<"com.braintribe.model.resource.specification.PhysicalDimensionSpecification", {
			heightInCm: P<double, { nullable: false }>;
			widthInCm: P<double, { nullable: false }>;
		}>;

		const PixelDimensionSpecification: hc.reflection.EntityType<PixelDimensionSpecification>;
		type PixelDimensionSpecification = ResourceSpecification &
		  Entity<"com.braintribe.model.resource.specification.PixelDimensionSpecification", {
			pixelHeight: P<integer, { nullable: false }>;
			pixelWidth: P<integer, { nullable: false }>;
		}>;

		const RasterImageSpecification: hc.reflection.EntityType<RasterImageSpecification>;
		type RasterImageSpecification = ImageSpecification & PixelDimensionSpecification &
		  Entity<"com.braintribe.model.resource.specification.RasterImageSpecification">;

		const VectorImageSpecification: hc.reflection.EntityType<VectorImageSpecification>;
		type VectorImageSpecification = ImageSpecification &
		  Entity<"com.braintribe.model.resource.specification.VectorImageSpecification">;

	}

}
